class Solution {
public:
    long long smallestNumber(long long num) {
        if (num == 0) return 0;

        long long n = num < 0 ? -num : num;
        int count[10] = {0};

        while (n > 0) {
            count[n % 10]++;
            n /= 10;
        }

        long long result = 0;

        if (num > 0) {
            for (int d = 1; d <= 9; d++) {
                if (count[d] > 0) {
                    result = result * 10 + d;
                    count[d]--;
                    break;
                }
            }
            for (int d = 0; d <= 9; d++) {
                while (count[d] > 0) {
                    result = result * 10 + d;
                    count[d]--;
                }
            }
        } else {
            for (int d = 9; d >= 0; d--) {
                while (count[d] > 0) {
                    result = result * 10 + d;
                    count[d]--;
                }
            }
            result = -result;
        }

        return result;
    }
};
